:root{--primary:#1b8168;--primary-soft:#dcf5ec;--primary-fg:#117b63;--accent-soft:#eaf2ce;--accent-fg:#56701f;
--cream:#f4f8f0;--stage:#edf1ea;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;
--teal-soft:#d9ecec;--danger:#b23b3b;--danger-soft:#f6e4e2;}
*{box-sizing:border-box}
body{background:var(--stage);font-family:Figtree,'Segoe UI',system-ui,sans-serif;color:var(--ink);margin:0}
.phone{max-width:400px;margin:16px auto;background:var(--cream);border-radius:24px;padding:16px;min-height:600px}
.wide{max-width:900px;margin:16px auto;background:var(--cream);border-radius:24px;padding:20px}
h1,h2,h3{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;margin:0}
h1{font-size:22px}h2{font-size:17px;margin:18px 0 8px}h3{font-size:14px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:12px;margin-top:10px}
.muted{color:var(--ink-soft);font-size:12px}
.gallery{aspect-ratio:4/3;background:var(--paper);border:1px solid var(--line);border-radius:16px;display:flex;align-items:center;justify-content:center;color:var(--ink-soft)}
.chip{display:inline-flex;align-items:center;gap:4px;border-radius:10px;padding:3px 8px;font-size:11px;font-weight:800}
.gift{background:var(--primary-soft);color:var(--primary-fg)}
.swap{background:var(--accent-soft);color:var(--accent-fg)}
.res{background:var(--teal-soft);color:var(--ink)}
.priv{background:var(--stage);color:var(--ink-soft);border:1px solid var(--line-strong)}
.btn{display:block;width:100%;border:0;border-radius:12px;padding:12px;font-weight:800;font-size:14px;margin-top:8px;text-align:center;cursor:pointer;font-family:inherit}
.btn-primary{background:var(--primary);color:#fff}
.btn-outline{background:var(--paper);color:var(--primary-fg);border:1.5px solid var(--primary)}
.btn-ghost{background:transparent;color:var(--primary-fg);text-decoration:underline}
.btn[aria-disabled=true]{opacity:.5}
.row{display:flex;gap:10px;align-items:center}
.ctx{display:flex;gap:10px;padding:10px 0;border-top:1px solid var(--line)}
.ctx:first-child{border-top:0}
.date{min-width:46px;text-align:center;background:var(--primary-soft);color:var(--primary-fg);border-radius:10px;padding:4px;font-weight:800;font-size:12px}
.pin{font-size:13px}
.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.tile{position:relative;background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:10px;display:flex;flex-direction:column;cursor:pointer}
.thumb{aspect-ratio:1;background:var(--cream);border-radius:12px;display:flex;align-items:center;justify-content:center;color:var(--ink-soft);font-size:11px}
.tname{font-weight:700;font-size:13px;margin-top:8px}
.badges{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}
.dim .thumb{opacity:.6}
.prow{display:flex;gap:10px;align-items:center;padding:8px 0;border-top:1px solid var(--line);cursor:pointer}
.pthumb{width:48px;height:48px;border-radius:10px;background:var(--cream);flex:none}
.tabs{display:flex;gap:6px;margin:10px 0}
.tab{border-radius:999px;padding:6px 12px;font-size:12px;font-weight:700;background:var(--paper);border:1px solid var(--line)}
.tab.on{background:var(--ink);color:#fff}
.counts{display:flex;gap:10px}
.count{flex:1;background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:12px;text-align:center}
.count b{display:block;font-size:22px;font-family:'Bricolage Grotesque',sans-serif}
select,.select{width:100%;padding:10px;border-radius:12px;border:1px solid var(--line-strong);background:var(--paper);font:inherit;font-size:14px}
.toggle{display:inline-flex;border:1px solid var(--line-strong);border-radius:10px;overflow:hidden;font-size:12px;font-weight:700}
.toggle span{padding:6px 10px;background:var(--paper)}
.toggle span.on{background:var(--ink);color:#fff}
.sheet{background:var(--paper);border-radius:20px 20px 0 0;padding:16px;margin:-16px;margin-top:180px;min-height:420px;box-shadow:0 -8px 30px rgb(0 0 0 /.15)}
.scrim{background:rgb(20 28 24 / .55);border-radius:24px;padding:16px;max-width:400px;margin:16px auto;min-height:640px}
.radio{display:flex;gap:10px;align-items:flex-start;padding:10px;border:1px solid var(--line);border-radius:12px;margin-top:8px}
.radio.on{border-color:var(--primary);background:var(--primary-soft)}
.dot{width:16px;height:16px;border-radius:50%;border:2px solid var(--line-strong);margin-top:2px;flex:none}
.radio.on .dot{border:5px solid var(--primary)}
.note{background:var(--accent-soft);border-radius:12px;padding:10px;font-size:12px;margin-top:10px}
.status{border-radius:14px;padding:12px;background:var(--teal-soft);margin-top:10px}
.loc{display:flex;gap:8px;align-items:flex-start}
.item-row{display:flex;gap:10px;align-items:flex-start}
.label{font-size:12px;font-weight:700;color:var(--ink-soft);margin-bottom:4px}

